using System;using UnityEngine;
public static class PvpNativePredictionTests {
 static int checks;static void Check(bool ok,string reason){checks++;if(!ok)throw new Exception("Native prediction: "+reason);}
 static PvpPredictedMotion At(float x){return new PvpPredictedMotion{position=Vector3.right*x,rotation=Quaternion.identity,velocity=Vector3.right*3};}
 public static void Run(){checks=0;var queue=new PvpNativeInputQueue();
 Check(queue.Enqueue(new PvpNativeDrive{sequence=1,throttle=2,steer=-2}),"finite controls accepted");Check(!queue.Enqueue(new PvpNativeDrive{sequence=1}),"duplicate discarded");Check(!queue.Enqueue(new PvpNativeDrive{sequence=2,steer=float.NaN}),"nonfinite rejected");var a=queue.Take();Check(a.sequence==1&&a.throttle==1&&a.steer==-1&&queue.Applied==1,"ordered host control and exact processed id, bounds clamped");
 for(int i=2;i<=45;i++)queue.Enqueue(new PvpNativeDrive{sequence=i});Check(queue.Count==32&&queue.Take().sequence==14,"backlog bounded without fabricating poses");queue.Clear();Check(queue.Received==0&&queue.Applied==0&&queue.Enqueue(new PvpNativeDrive{sequence=1}),"reconnect resets input numbering");
 var history=new PvpNativePredictionHistory();for(int i=1;i<=10;i++)history.Remember(i,At(i));Vector3 p,v,w;Quaternion q;
 Check(history.Error(5,At(5.2f),out p,out q,out v,out w)&&Mathf.Abs(p.x-.2f)<.001f,"delayed ack compared with old step, not current moving position");history.Shift(p,q,v,w);history.Error(5,At(5.2f),out p,out q,out v,out w);Check(p.magnitude<.001f,"history shifts avoid applying same correction twice");Check(!history.Error(5,At(9),out p,out q,out v,out w),"duplicate ack cannot relabel later physics as the same input step");Check(!history.Error(4,At(4),out p,out q,out v,out w),"stale acknowledgement ignored");Check(!history.Error(0,At(0),out p,out q,out v,out w),"unprocessed snapshot cannot drag immediate owner back");
 for(int i=11;i<=600;i++)history.Remember(i,At(i));Check(history.Count==256&&!history.Error(5,At(5),out p,out q,out v,out w),"state history bounded");history.Clear();Check(history.Count==0&&history.LastAck==0,"new session drops prediction history");
 var root=new GameObject("native prediction correction");try{var taxi=root.AddComponent<TaxiController>();taxi.body=root.AddComponent<Rigidbody>();taxi.body.useGravity=false;
 var prediction=new PvpNativePrediction(taxi);prediction.Receive(0,At(0),true,false);prediction.Step(new PvpNativeDrive{sequence=1,throttle=1},.02f);Check(taxi.autoThrottle==1&&!taxi.autoBrake,"local native controls apply without a response");
 taxi.body.position=Vector3.right;prediction.Step(new PvpNativeDrive{sequence=2,brake=true},.02f);prediction.Receive(1,At(1.2f),false,false);float start=taxi.body.position.x;prediction.Step(new PvpNativeDrive{sequence=3},.02f);Check(taxi.body.position.x>start&&taxi.body.position.x<start+.061f&&prediction.HardResets==1,"small error smooths with bounded physical displacement");
 prediction.Receive(3,At(50),false,false);Check(prediction.HardResets==2&&Mathf.Abs(taxi.body.position.x-50)<.001f,"large reset accepts host pose");prediction.Receive(0,At(50),false,true);prediction.Step(new PvpNativeDrive{sequence=4,throttle=1},.02f);Check(taxi.autoBrake&&taxi.autoThrottle==0,"host service lock wins over local throttle");
 }finally{UnityEngine.Object.DestroyImmediate(root);}Debug.Log("PVP_NATIVE_PREDICTION_OK checks="+checks);
 }
 public static void FreeGuide(){var empty=JsonUtility.FromJson<PvpNativeActor>(JsonUtility.ToJson(new PvpNativeActor()));Check(!empty.hasFreeRoute,"absent inline guide has explicit presence bit despite Unity null reconstruction");var map=PvpCityMap.Create();var graph=new HdRoadGraph(map);var route=graph.Forward(0,2);var wire=PvpNativeFreeRoute.Capture(graph,route);var restored=wire.Restore(graph,null);
 Check(restored!=null&&Mathf.Abs(restored.path.length-route.path.length)<.01f,"host free guide reproduces directed cut geometry");Check(ReferenceEquals(restored,wire.Restore(graph,restored)),"unchanged free guide reuses path instead of repeated rebuild");var copy=JsonUtility.FromJson<PvpNativeFreeRoute>(JsonUtility.ToJson(wire));Check(Mathf.Abs(copy.Restore(graph,null).path.length-route.path.length)<.01f,"free guide survives actual JSON wire format");bool rejected=false;try{new PvpNativeFreeRoute{edges=new[]{-1}}.Restore(graph,null);}catch(ArgumentException){rejected=true;}Check(rejected,"invalid free guide edge rejected");Debug.Log("PVP_NATIVE_FREE_GUIDE_OK checks=5");}
 public static void Build(){Run();FreeGuide();PvpNativeWheelTests.Run();PvpNativePoseTests.Run();BuildProbeOnly();}
 public static void BuildProbeOnly(){ProjectMapBuild.Prepare();typeof(PrototypeBuild).GetMethod("BuildAt",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static).Invoke(null,new object[]{"../../artifacts/pvp/owner-prediction-ready/EungyeTaxi.exe","eungye"});}
}
